import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"18、【蛊】 巽下艮上","description":"温公易说 - 18、【蛊】 巽下艮上","frontmatter":{"title":"18、【蛊】 巽下艮上","description":"温公易说 - 18、【蛊】 巽下艮上"},"headers":[],"relativePath":"zh/classics/wengong/019.md","filePath":"zh/classics/wengong/019.md"}'),n={name:"zh/classics/wengong/019.md"};function l(t,a,s,o,d,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="_18、【蛊】-巽下艮上" tabindex="-1">18、【蛊】 巽下艮上 <a class="header-anchor" href="#_18、【蛊】-巽下艮上" aria-label="Permalink to “18、【蛊】 巽下艮上”">​</a></h1><h3 id="彖曰-蛊-刚上而柔下-巽而止-蛊。蛊元亨而天下治也。利涉大川-往有事也。先甲三日-后甲三日-终则有始-天行也。" tabindex="-1">彖曰：蛊，刚上而柔下，巽而止，蛊。蛊元亨而天下治也。利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。 <a class="header-anchor" href="#彖曰-蛊-刚上而柔下-巽而止-蛊。蛊元亨而天下治也。利涉大川-往有事也。先甲三日-后甲三日-终则有始-天行也。" aria-label="Permalink to “彖曰：蛊，刚上而柔下，巽而止，蛊。蛊元亨而天下治也。利涉大川，往有事也。先甲三日，后甲三日，终则有始，天行也。”">​</a></h3><p>蛊者，物有蠹敝而事之也。事之者，治之也。除蠹补敝，故大通也。刚上而柔下，善登而恶降也。巽而止之，利以济难也。甲者，生之始，为仁为德。庚者，杀之终，为义为刑。先之三日以谨其始，后之三日以慎其终。蛊以少阳在上而行令，故主仁。巽以少阴在上而行令，故主义。天以阴阳终始，万物君子以仁义修身，以德刑治国，各有其事也。</p><h3 id="象曰-山下有风-蛊。君子以振民育德。" tabindex="-1">象曰：山下有风，蛊。君子以振民育德。 <a class="header-anchor" href="#象曰-山下有风-蛊。君子以振民育德。" aria-label="Permalink to “象曰：山下有风，蛊。君子以振民育德。”">​</a></h3><p>艮为丘为山，巽为风为号令。君子洗濯其心，一以待人，以育德于上。山之象也，发号施令，革弊除蠹，以振民于下。风之象也。</p><h3 id="初六-干父之蛊-有子考无咎-厉终吉-象曰-干父之蛊-意承考也。" tabindex="-1">初六：干父之蛊，有子考无咎，厉终吉 象曰：干父之蛊，意承考也。 <a class="header-anchor" href="#初六-干父之蛊-有子考无咎-厉终吉-象曰-干父之蛊-意承考也。" aria-label="Permalink to “初六：干父之蛊，有子考无咎，厉终吉 象曰：干父之蛊，意承考也。”">​</a></h3><p>子者所以承父之事而成之，臣者所以成君之事而终之。天下之事大矣，多矣，自非圣人不能无过。故子能葢父之愆，臣能掩君之恶，然后为干蛊也。以秦始汉武之奢汰骄暴，相逺也无几耳。始皇得胡亥以为子，李斯以为臣，不旋踵而亡矣。天下后世之言恶者必归焉。武帝得昭帝以为子，霍光以为臣，而国家乂宁，后世称之为明君。隋唐之祖亦然，故必有贤子然后考得无咎也。干事之始，敢自安乎？故战战兢兢，乃得终吉也。夫事有蛊敝，不可不更。臣子之心非以高君父而自名也，欲以掩恶而全美，故曰意承考也。</p><h3 id="九二-干母之蛊-不可贞-象曰-干母之蛊-得中道也。" tabindex="-1">九二：干母之蛊，不可贞 象曰：干母之蛊，得中道也。 <a class="header-anchor" href="#九二-干母之蛊-不可贞-象曰-干母之蛊-得中道也。" aria-label="Permalink to “九二：干母之蛊，不可贞 象曰：干母之蛊，得中道也。”">​</a></h3><h3 id="九三-干父之蛊-小有悔-无大咎-象曰-干父之蛊-终无咎也。" tabindex="-1">九三：干父之蛊，小有悔，无大咎 象曰：干父之蛊，终无咎也。 <a class="header-anchor" href="#九三-干父之蛊-小有悔-无大咎-象曰-干父之蛊-终无咎也。" aria-label="Permalink to “九三：干父之蛊，小有悔，无大咎 象曰：干父之蛊，终无咎也。”">​</a></h3><p>亲有过，下气怡声以谏，礼也。三以重刚干之故，小有悔也。然不失其正，故无大咎也。</p><h3 id="六四-裕父之蛊-往见吝-象曰-裕父之蛊-往未得也。" tabindex="-1">六四：裕父之蛊，往见吝 象曰：裕父之蛊，往未得也。 <a class="header-anchor" href="#六四-裕父之蛊-往见吝-象曰-裕父之蛊-往未得也。" aria-label="Permalink to “六四：裕父之蛊，往见吝 象曰：裕父之蛊，往未得也。”">​</a></h3><p>六四裕父之蛊，楚屈到嗜芰，有疾，属之曰祭我必以芰。及祥，宗老将荐芰，屈建命去之曰：国君有牛享，大夫有羊馈，士有豚豕之奠，庶人有鱼炙之荐，不羞珍异，不陈庶侈。夫子不以其私欲干国之典，遂不用。易曰：裕父之蛊，往见吝。裕之为言饶也，益也。父不义而顺之，是裕之也。往而不变，斯可丑也。</p><h3 id="六五-干父之蛊-用誉-象曰-干父用誉-承以德也。" tabindex="-1">六五：干父之蛊，用誉 象曰：干父用誉，承以德也。 <a class="header-anchor" href="#六五-干父之蛊-用誉-象曰-干父用誉-承以德也。" aria-label="Permalink to “六五：干父之蛊，用誉 象曰：干父用誉，承以德也。”">​</a></h3><p>五居盛位，以柔承刚，又有中和之德，故有誉也。</p><h3 id="上九-不事王侯-高尚其志-象曰-不事王侯-志可则也。" tabindex="-1">上九：不事王侯，高尚其志 象曰：不事王侯，志可则也。 <a class="header-anchor" href="#上九-不事王侯-高尚其志-象曰-不事王侯-志可则也。" aria-label="Permalink to “上九：不事王侯，高尚其志 象曰：不事王侯，志可则也。”">​</a></h3><p>阳者君子之象，致仕而无位，年高而德尊。虽不能以力干事，而智虑深逺，志可法也。故先王养老乞言焉，非夫矫亢以惊俗，虚骄而无用者也。</p>',16)])])}const b=e(n,[["render",l]]);export{_ as __pageData,b as default};
